DEFAULT_GSHEET_URL = "https://docs.google.com/spreadsheets/d/1VkcMVInSbhiXxBMQpWvT1Ns-Rl6gRvYNTEhL9kV5Tk8/edit?gid=1940670585#gid=1940670585"  # მაგ: "https://docs.google.com/spreadsheets/d/1BxiMVs0XRA5.../edit"

# ჩაშენებული სარეზერვო ბაზა (Embedded Backup Dataset - 4,615 ჩანაწერი)
EMBEDDED_CSV_GZ_B64 = ""

def load_google_sheet(url: str, sheet_name: str = None) -> pd.DataFrame:
    clean_url = str(url).strip()
    m = re.search(r'/spreadsheets/d/([a-zA-Z0-9-_]+)', clean_url)
    if not m:
        raise ValueError("არასწორი Google Sheets ბმულია. დარწმუნდით, რომ ბმული შეიცავს /spreadsheets/d/...-ს.")
    sheet_id = m.group(1)
    
    gid_match = re.search(r'[#&?]gid=([0-9]+)', clean_url)
    gid = gid_match.group(1) if gid_match else '0'
    
    urls_to_try = []
    if sheet_name and sheet_name.strip():
        encoded = urllib.parse.quote(sheet_name.strip())
        urls_to_try.append(f"https://docs.google.com/spreadsheets/d/{sheet_id}/gviz/tq?tqx=out:csv&sheet={encoded}")
    
    urls_to_try.append(f"https://docs.google.com/spreadsheets/d/{sheet_id}/export?format=csv&gid={gid}")
    urls_to_try.append(f"https://docs.google.com/spreadsheets/d/{sheet_id}/gviz/tq?tqx=out:csv&gid={gid}")
    
    last_err = None
    for target_url in urls_to_try:
        try:
            df = pd.read_csv(target_url)
            if len(df.columns) > 0 and not any('<!DOCTYPE' in str(c) for c in df.columns):
                return df
        except Exception as e:
            last_err = e
            continue
            
    if last_err:
        raise last_err
    raise ValueError("Google Sheet-ის ჩამოტვირთვა ვერ მოხერხდა. დარწმუნდით, რომ ფაილი გაზიარებულია: Share -> Anyone with the link can view.")

@st.cache_data(show_spinner=False, ttl=300)
def fetch_cached_sheet(url: str, sheet_name: str = None) -> pd.DataFrame:
    return load_google_sheet(url, sheet_name)
