# -----------------------------------------------------------------------------
# 2.5 PDF აგროვების რეპორტის ავტომატური პარსერი (PDF PARSER FOR PICKING MANIFESTS)
# -----------------------------------------------------------------------------
def normalize_product_name(p_name, catalog):
    """ნორმალიზებას უკეთებს პროდუქტის სახელს კატალოგთან დასაკავშირებლად."""
    p_clean = ' '.join(str(p_name).split()).strip()
    if not catalog or p_clean in catalog:
        return p_clean
    
    p_lower = p_clean.lower()
    for cat_p in catalog:
        if cat_p.lower() == p_lower:
            return cat_p
            
    clean_key = re.sub(r'[\s,.-]', '', p_lower)
    for cat_p in catalog:
        if re.sub(r'[\s,.-]', '', cat_p.lower()) == clean_key:
            return cat_p
            
    return p_clean

def parse_picking_pdf(file_obj, catalog=None):
    """
    აგროვების PDF ფაილის (მაგ. აგროვება.pdf) ავტომატური პარსერი.
    აბრუნებს DataFrame-ს სვეტებით: ['მანქანა', 'პროდუქტი', 'რაოდენობა (ცალი)', 'ჯგუფი']
    """
    if pdfplumber is None and pypdf is None:
        raise ImportError("PDF ფაილის წასაკითხად საჭიროა pypdf ან pdfplumber ბიბლიოთეკა. გაუშვით ტერმინალში: pip install pypdf pdfplumber")
        
    records = []
    
    # 1. პირველ რიგში pdfplumber (ცხრილური ბადის ზუსტი ამოცნობა)
    if pdfplumber is not None:
        try:
            if hasattr(file_obj, 'seek'):
                file_obj.seek(0)
            with pdfplumber.open(file_obj) as pdf:
                current_truck = None
                current_group = None
                
                for page in pdf.pages:
                    text = page.extract_text() or ''
                    
                    # ვეძებთ მანქანის ნომერს/მოდელს
                    m_truck = re.search(r'მანქანა:\s*([^\n\r#]+)', text)
                    if m_truck and m_truck.group(1).strip():
                        raw_truck = m_truck.group(1).strip()
                    else:
                        m_truck2 = re.search(r'მანქანა:\s*\n\s*([^\n\r#]+)', text)
                        raw_truck = m_truck2.group(1).strip() if m_truck2 else ''
                        
                    if raw_truck:
                        clean_truck = re.split(r'აგროვებ|ტვირთამწეობ|დოკუმენტ|შტრიხკოდ', raw_truck)[0].strip()
                        if clean_truck:
                            current_truck = clean_truck
                            
                    # ვეძებთ აგროვების ჯგუფს
                    m_grp = re.search(r'აგროვების\s+ჯგუფი:\s*([^\n\r]+)', text)
                    if m_grp:
                        current_group = m_grp.group(1).strip()
                        
                    tables = page.extract_tables()
                    page_found = 0
                    
                    if tables:
                        for table in tables:
                            if not table or len(table) < 2:
                                continue
                            
                            header = table[0]
                            prod_idx, qty_idx = None, None
                            for c_idx, cell in enumerate(header):
                                if not cell: continue
                                c_clean = str(cell).replace('\n', ' ').strip()
                                if any(k in c_clean for k in ['საქონელ', 'პროდუქტ', 'დასახელებ']):
                                    prod_idx = c_idx
                                elif any(k in c_clean for k in ['(სულ)', 'რაო-ბა (სულ)', 'სულ']):
                                    qty_idx = c_idx
                                    
                            if prod_idx is None and len(header) >= 4: prod_idx = 3
                            if qty_idx is None and len(header) >= 5: qty_idx = 4
                            
                            for row in table[1:]:
                                if not row or len(row) <= max(prod_idx or 0, qty_idx or 0):
                                    continue
                                p_cell = str(row[prod_idx]).strip() if prod_idx is not None else ''
                                q_cell = str(row[qty_idx]).strip() if qty_idx is not None else ''
                                
                                if not p_cell or any(k in p_cell for k in ['საქონელი', 'სულ რაოდენობა', 'ხელმოწერა', 'შტრიხკოდი', 'აგროვების ნომერი']):
                                    continue
                                    
                                clean_qty_str = re.sub(r'[^\d.]', '', q_cell)
                                try:
                                    qty_val = float(clean_qty_str)
                                except ValueError:
                                    continue
                                    
                                if qty_val > 0 and len(p_cell) > 2 and current_truck:
                                    clean_prod = ' '.join(p_cell.split()).strip()
                                    if catalog:
                                        clean_prod = normalize_product_name(clean_prod, catalog)
                                    records.append({
                                        'მანქანა': current_truck,
                                        'პროდუქტი': clean_prod,
                                        'რაოდენობა (ცალი)': qty_val,
                                        'ჯგუფი': current_group or ''
                                    })
                                    page_found += 1
                                    
                    # ტექსტური fallback თუ ცხრილის გარეშეა გვერდი
                    if page_found == 0 and text and current_truck:
                        for line in text.split('\n'):
                            m_line = re.match(r'^\s*(\d+)\s+(\d+)\s+([0-9A-Za-z]+)\s+(.+?)\s+(\d+(?:\.\d+)?)(?:\s+\d+)*\s*$', line)
                            if m_line:
                                p_name = m_line.group(4).strip()
                                q_val = float(m_line.group(5))
                                if q_val > 0 and len(p_name) > 2:
                                    clean_prod = ' '.join(p_name.split()).strip()
                                    if catalog:
                                        clean_prod = normalize_product_name(clean_prod, catalog)
                                    records.append({
                                        'მანქანა': current_truck,
                                        'პროდუქტი': clean_prod,
                                        'რაოდენობა (ცალი)': q_val,
                                        'ჯგუფი': current_group or ''
                                    })
        except Exception as e:
            pass

    # 2. თუ pdfplumber-ით ვერაფერი ამოიღო, ვცადოთ pypdf
    if not records and pypdf is not None:
        try:
            if hasattr(file_obj, 'seek'):
                file_obj.seek(0)
            reader = pypdf.PdfReader(file_obj)
            current_truck = None
            current_group = None
            
            for page in reader.pages:
                text = page.extract_text() or ''
                m_truck = re.search(r'მანქანა:\s*([^\n\r#]+)', text)
                if m_truck and m_truck.group(1).strip():
                    raw_truck = m_truck.group(1).strip()
                else:
                    m_truck2 = re.search(r'მანქანა:\s*\n\s*([^\n\r#]+)', text)
                    raw_truck = m_truck2.group(1).strip() if m_truck2 else ''
                    
                if raw_truck:
                    clean_truck = re.split(r'აგროვებ|ტვირთამწეობ|დოკუმენტ|შტრიხკოდ', raw_truck)[0].strip()
                    if clean_truck: current_truck = clean_truck
                
                m_grp = re.search(r'აგროვების\s+ჯგუფი:\s*([^\n\r]+)', text)
                if m_grp: current_group = m_grp.group(1).strip()
                
                if current_truck:
                    for line in text.split('\n'):
                        m_line = re.match(r'^\s*(\d+)\s+(\d+)\s+([0-9A-Za-z]+)\s+(.+?)\s+(\d+(?:\.\d+)?)(?:\s+\d+)*\s*$', line)
                        if m_line:
                            p_name = m_line.group(4).strip()
                            q_val = float(m_line.group(5))
                            if q_val > 0 and len(p_name) > 2:
                                clean_prod = ' '.join(p_name.split()).strip()
                                if catalog:
                                    clean_prod = normalize_product_name(clean_prod, catalog)
                                records.append({
                                    'მანქანა': current_truck,
                                    'პროდუქტი': clean_prod,
                                    'რაოდენობა (ცალი)': q_val,
                                    'ჯგუფი': current_group or ''
                                })
        except Exception as e:
            pass
            
    df_res = pd.DataFrame(records)
    return df_res

# 3. საანგარიშო ძრავი (CALCULATION ENGINE)
# -----------------------------------------------------------------------------
def calculate_loading(df_picking, catalog, fleet, params):
    col_truck, col_prod, col_pcs = None, None, None
    for c in df_picking.columns:
        c_str = str(c).strip().lower()
        if any(k in c_str for k in ['მანქანა', 'ტრანსპორტ', 'ავტომობილ', 'truck']):
            col_truck = c
        elif any(k in c_str for k in ['პროდუქტ', 'დასახელებ', 'საქონელ', 'ნომენკლატურ', 'product', 'item']):
            col_prod = c
        elif 'ცალი' in c_str or 'pcs' in c_str:
            col_pcs = c
        elif any(k in c_str for k in ['რაოდენობა', 'qty', 'quantity']) and not col_pcs:
            col_pcs = c
            
    if not col_truck or not col_prod or not col_pcs:
        raise ValueError("ფაილში ვერ მოიძებნა საჭირო სვეტები: მანქანა, პროდუქტი, რაოდენობა (ცალი)")

    df = df_picking[[col_truck, col_prod, col_pcs]].dropna().copy()
    df[col_truck] = df[col_truck].astype(str).str.strip()
    df[col_prod] = df[col_prod].astype(str).str.replace('\xa0', ' ').str.replace(r'\s+', ' ', regex=True).str.strip()
    df[col_pcs] = pd.to_numeric(df[col_pcs], errors='coerce').fillna(0)
    df = df[(df[col_truck] != 'მანქანა') & (df[col_pcs] > 0)]

    # მკაცრი კონსოლიდაცია: ვაჯამებთ ცალებს და ვითვლით რამდენი შეკვეთა გაერთიანდა ერთ მწკრივში
    agg = df.groupby([col_truck, col_prod]).agg(
        pcs=(col_pcs, 'sum'),
        orders=(col_pcs, 'count')
    ).reset_index()
    trucks = agg[col_truck].unique()

    summary_rows = []
    truck_details = {}

    for truck in trucks:
        t_df = agg[agg[col_truck] == truck]
        nab_pcs, nab_pks = 0, 0
        water_items, bal_items, juice_items, marneuli_items = [], [], [], []
        tot_truck_pcs = 0
        tot_truck_wt = 0.0
        itemized_list = []

        for _, row in t_df.iterrows():
            p_name = row[col_prod]
            pcs = float(row['pcs'])
            orders_cnt = int(row['orders'])
            cat_entry = catalog.get(p_name, {
                'grp': 'სხვა',
                'upk': 1.0,
                'wt': 1.0,
                'pks_pal': 0.0,
                'pcs_pal': 0.0,
                'short': p_name
            })

            grp = cat_entry['grp']
            upk = cat_entry['upk']
            wt = cat_entry['wt']
            pks = pcs / upk if upk > 0 else pcs
            total_wt = pcs * wt

            tot_truck_pcs += pcs
            tot_truck_wt += total_wt

            # პალეტური განაწილების დეტალური ჩანაწერი
            pks_pal = cat_entry['pks_pal']
            if pks_pal > 0 and pks >= pks_pal:
                full_pal_cnt = int(pks // pks_pal)
                rem_p = round(pks - (full_pal_cnt * pks_pal), 1)
                if rem_p > 0:
                    pal_note = f"{full_pal_cnt} სრული პალ + {rem_p:g} შეკვ ნაკრებში"
                else:
                    pal_note = f"{full_pal_cnt} სრული პალეტი"
            else:
                if grp == 'ბალონი':
                    pal_note = f"{int(round(pcs))} ცალი ნაკრებში"
                else:
                    pal_note = f"{round(pks, 1):g} შეკვ ნაკრებში"

            item_data = {
                'name': p_name,
                'pcs': pcs,
                'pks': pks,
                'wt': total_wt,
                'upk': upk,
                'pks_pal': cat_entry['pks_pal'],
                'pcs_pal': cat_entry['pcs_pal'],
                'short': cat_entry['short'],
                'grp': grp,
                'orders': orders_cnt,
                'pal_note': pal_note
            }
            itemized_list.append(item_data)

            if grp == 'ნაბეღლავი 1ლ':
                nab_pcs += pcs
                nab_pks += pks
            elif grp == 'წყალი':
                water_items.append(item_data)
            elif grp == 'ბალონი':
                bal_items.append(item_data)
            elif grp == 'წვენები':
                juice_items.append(item_data)
            elif grp == 'მარნეული':
                marneuli_items.append(item_data)
            else:
                if 'ნაბეღლავი' in p_name and '1 ლ' in p_name:
                    nab_pcs += pcs
                    nab_pks += pks
                elif 'წყალი' in p_name:
                    water_items.append(item_data)
                elif any(x in p_name for x in ['ბალონი', '10 ლ', '6 ლ', '8 ლ', '3.5 ლ']):
                    bal_items.append(item_data)
                elif 'მარნეული' in p_name:
                    marneuli_items.append(item_data)
                else:
                    juice_items.append(item_data)

        # 1. ნაბეღლავი 1ლ
        nab_norm = params['nab_norm']
        if nab_pks <= 0:
            nab_text, nab_pal = "-", 0
        else:
            full_pal = int(round(nab_pks)) // nab_norm
            rem_pks = int(round(nab_pks)) % nab_norm
            nab_pal = math.ceil(round(nab_pks) / nab_norm)
            if full_pal == 0: nab_text = f"{int(round(nab_pks))} შეკვ"
            elif rem_pks == 0: nab_text = f"{full_pal} პალ"
            else: nab_text = f"{full_pal} პალ + {rem_pks} შეკვ"

        # 2. წყალი (სხვა)
        tot_wat_pks = sum(x['pks'] for x in water_items)
        if tot_wat_pks <= 0:
            wat_text, wat_pal = "-", 0
        else:
            wat_fps, wat_fp_count, wat_rem_pks = [], 0, 0
            for item in water_items:
                norm = item['pks_pal']
                if norm > 0 and item['pks'] >= norm:
                    fp = int(item['pks'] // norm)
                    wat_fp_count += fp
                    rem = item['pks'] - (fp * norm)
                    wat_rem_pks += rem
                    wat_fps.append(f"{fp} პალ {item['short']}")
                else:
                    wat_rem_pks += item['pks']
            
            wat_mixed_limit = params['water_mixed_limit']
            mixed_pal = math.ceil(round(wat_rem_pks) / wat_mixed_limit) if round(wat_rem_pks) > 0 else 0
            wat_pal = wat_fp_count + mixed_pal

            if wat_fp_count == 0:
                if round(tot_wat_pks) <= wat_mixed_limit:
                    wat_text = f"{int(round(tot_wat_pks))} შეკვ"
                else:
                    wat_text = f"{wat_pal} პალ ({int(round(tot_wat_pks))} შეკვ ნაკრები)"
            else:
                sub_parts = list(wat_fps)
                if round(wat_rem_pks) > 0:
                    sub_parts.append(f"{int(round(wat_rem_pks))} შეკვ ნაკრები")
                wat_text = f"{wat_pal} პალ (" + ", ".join(sub_parts) + ")"

        # 3. ბალონები
        tot_bal_pcs = sum(x['pcs'] for x in bal_items)
        bal_norm = params['bal_norm']
        if tot_bal_pcs <= 0:
            bal_text, bal_pal = "-", 0
        elif tot_bal_pcs <= bal_norm:
            bal_text, bal_pal = "1 პალ", 1
        else:
            bal_pal = math.ceil(round(tot_bal_pcs) / bal_norm)
            bal_text = f"{bal_pal} პალ ({int(round(tot_bal_pcs))} ც ნაკრები)"

        # 4. წვენები
        tot_juice_wt = sum(x['wt'] for x in juice_items)
        tot_juice_pks = sum(x['pks'] for x in juice_items)
        juice_limit = params['juice_wt_limit']
        if tot_juice_wt <= 0:
            juice_text, juice_pal = "-", 0
        elif tot_juice_wt <= juice_limit:
            juice_text, juice_pal = "1 პალ", 1
        else:
            j_fps, j_fp_count, j_rem_wt = [], 0, 0.0
            for item in juice_items:
                norm = item['pks_pal']
                if norm > 0 and item['pks'] >= norm:
                    fp = int(item['pks'] // norm)
                    j_fp_count += fp
                    rem_pks = item['pks'] - (fp * norm)
                    j_rem_wt += rem_pks * (item['wt'] / item['pks'] if item['pks'] > 0 else 0)
                    j_fps.append(f"{fp} პალ {item['short']}")
                else:
                    j_rem_wt += item['wt']

            j_rem_pal = math.ceil(j_rem_wt / juice_limit) if j_rem_wt > 0 else 0
            juice_pal = j_fp_count + j_rem_pal
            if j_fp_count == 0:
                juice_text = f"{juice_pal} პალ ({int(round(tot_juice_pks))} შეკვ ნაკრები)"
            else:
                sub_parts = list(j_fps)
                rem_pks_tot = tot_juice_pks - sum(int(it['pks'] // it['pks_pal']) * it['pks_pal'] for it in juice_items if it['pks_pal'] > 0 and it['pks'] >= it['pks_pal'])
                if round(rem_pks_tot) > 0:
                    sub_parts.append(f"{int(round(rem_pks_tot))} შეკვ ნაკრები")
                juice_text = f"{juice_pal} პალ (" + ", ".join(sub_parts) + ")"

        # 5. მარნეული & იმპორტი
        tot_mar_wt = sum(x['wt'] for x in marneuli_items)
        tot_mar_pks = sum(x['pks'] for x in marneuli_items)
        mar_limit = params['marneuli_wt_limit']
        if tot_mar_wt <= 0:
            mar_text, mar_pal = "-", 0
        elif tot_mar_wt <= mar_limit:
            mar_text, mar_pal = "1 პალ", 1
        else:
            m_fps, m_fp_count, m_rem_wt = [], 0, 0.0
            for item in marneuli_items:
                norm = item['pks_pal']
                if norm > 0 and item['pks'] >= norm:
                    fp = int(item['pks'] // norm)
                    m_fp_count += fp
                    rem_pks = item['pks'] - (fp * norm)
                    m_rem_wt += rem_pks * (item['wt'] / item['pks'] if item['pks'] > 0 else 0)
                    m_fps.append(f"{fp} პალ {item['short']}")
                else:
                    m_rem_wt += item['wt']

            m_rem_pal = math.ceil(m_rem_wt / mar_limit) if m_rem_wt > 0 else 0
            mar_pal = m_fp_count + m_rem_pal
            if m_fp_count == 0:
                mar_text = f"{mar_pal} პალ ({int(round(tot_mar_pks))} შეკვ ნაკრები)"
            else:
                sub_parts = list(m_fps)
                rem_pks_tot = tot_mar_pks - sum(int(it['pks'] // it['pks_pal']) * it['pks_pal'] for it in marneuli_items if it['pks_pal'] > 0 and it['pks'] >= it['pks_pal'])
                if round(rem_pks_tot) > 0:
                    sub_parts.append(f"{int(round(rem_pks_tot))} შეკვ ნაკრები")
                mar_text = f"{mar_pal} პალ (" + ", ".join(sub_parts) + ")"

        total_pallets = nab_pal + wat_pal + bal_pal + juice_pal + mar_pal
        cap = fleet.get(truck, fleet.get(truck[:7], 4))
        diff = total_pallets - cap

        if diff > 0:
            status = f"🔴 გადაცილება: {diff} პალ"
            status_code = "OVERFLOW"
        elif diff < 0:
            status = f"🟢 თავისუფალია: {abs(diff)} პალ"
            status_code = "FREE"
        else:
            status = "🟢 თავისუფალია: 0 პალ"
            status_code = "FULL"

        summary_rows.append({
            'მანქანა': truck,
            'ნაბეღლავი 1ლ': nab_text,
            'წყალი (სხვა)': wat_text,
            'ბალონები': bal_text,
            'წვენები': juice_text,
            'მარნეული & იმპორტი': mar_text,
            'სულ ცალი': int(round(tot_truck_pcs)),
            'სულ წონა (კგ)': round(tot_truck_wt, 1),
            'სულ პალეტი': total_pallets,
            'ტევადობა': cap,
            'სტატუსი': status,
            'status_code': status_code,
            'pal_nab': nab_pal,
            'pal_wat': wat_pal,
            'pal_bal': bal_pal,
            'pal_jui': juice_pal,
            'pal_mar': mar_pal
        })

        truck_details[truck] = {
            'truck': truck,
            'cap': cap,
            'total_pal': total_pallets,
            'diff': diff,
            'status': status,
            'tot_pcs': tot_truck_pcs,
            'tot_wt': tot_truck_wt,
            'tot_pks': sum(x['pks'] for x in itemized_list),
            'tot_orders': sum(x['orders'] for x in itemized_list),
            'groups': {
                'ნაბეღლავი 1ლ': {'pal': nab_pal, 'text': nab_text, 'pcs': nab_pcs, 'pks': nab_pks, 'wt': nab_pcs * 1.0},
                'წყალი (სხვა)': {'pal': wat_pal, 'text': wat_text, 'pks': tot_wat_pks, 'items': water_items},
                'ბალონები': {'pal': bal_pal, 'text': bal_text, 'pcs': tot_bal_pcs, 'items': bal_items},
                'წვენები': {'pal': juice_pal, 'text': juice_text, 'wt': tot_juice_wt, 'pks': tot_juice_pks, 'items': juice_items},
                'მარნეული & იმპორტი': {'pal': mar_pal, 'text': mar_text, 'wt': tot_mar_wt, 'pks': tot_mar_pks, 'items': marneuli_items}
            },
            'items': itemized_list
        }

    return pd.DataFrame(summary_rows), truck_details

# -----------------------------------------------------------------------------
# 4. სუფთა და მსუბუქი EXCEL ექსპორტის გენერატორი (LIGHTWEIGHT EXCEL EXPORT)
# -----------------------------------------------------------------------------
def export_clean_excel(summary_df, catalog, fleet, params):
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "დატვირთვის შემაჯამებელი"
    ws.sheet_view.showGridLines = True

    font_title = Font(name="Calibri", size=14, bold=True, color="1F497D")
    font_header = Font(name="Calibri", size=11, bold=True, color="FFFFFF")
    font_data = Font(name="Calibri", size=10)
    font_bold = Font(name="Calibri", size=10, bold=True)
    
    fill_header = PatternFill(start_color="2F5496", end_color="2F5496", fill_type="solid")
    fill_zebra = PatternFill(start_color="F9FAFB", end_color="F9FAFB", fill_type="solid")
    fill_red = PatternFill(start_color="FDE8E8", end_color="FDE8E8", fill_type="solid")
    fill_green = PatternFill(start_color="DEF7EC", end_color="DEF7EC", fill_type="solid")
    font_red = Font(name="Calibri", size=10, bold=True, color="9B1C1C")
    font_green = Font(name="Calibri", size=10, bold=True, color="03543F")

    border_thin = Side(border_style="thin", color="D1D5DB")
    cell_border = Border(left=border_thin, right=border_thin, top=border_thin, bottom=border_thin)

    ws.cell(row=1, column=1, value="საწყობის დატვირთვის ოპერატიული შემაჯამებელი (სუფთა ვერსია)").font = font_title
    ws.cell(row=2, column=1, value=f"პარამეტრები: ნაბეღლავი 1ლ = {params['nab_norm']} შეკვ/პალ | წყალი = {params['water_mixed_limit']} შეკვ/პალ | ბალონი = {params['bal_norm']} ც/პალ | წვენები = {params['juice_wt_limit']} კგ | მარნეული = {params['marneuli_wt_limit']} კგ").font = Font(name="Calibri", size=9, italic=True, color="4B5563")

    cols = ['მანქანა', 'ნაბეღლავი 1ლ', 'წყალი (სხვა)', 'ბალონები', 'წვენები', 'მარნეული & იმპორტი', 'სულ ცალი', 'სულ წონა (კგ)', 'სულ პალეტი', 'ტევადობა', 'სტატუსი']
    
    for c_idx, col_name in enumerate(cols, 1):
        cell = ws.cell(row=4, column=c_idx, value=col_name)
        cell.font = font_header
        cell.fill = fill_header
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        cell.border = cell_border
    ws.row_dimensions[4].height = 28

    row_idx = 5
    for _, r_data in summary_df.iterrows():
        bg_fill = fill_zebra if row_idx % 2 == 0 else PatternFill(fill_type=None)
        
        for c_idx, col_name in enumerate(cols, 1):
            val = r_data[col_name]
            cell = ws.cell(row=row_idx, column=c_idx, value=val)
            cell.font = font_data
            cell.border = cell_border
            cell.fill = bg_fill
            
            if col_name in ['სულ ცალი', 'სულ წონა (კგ)', 'სულ პალეტი', 'ტევადობა']:
                cell.alignment = Alignment(horizontal="right", vertical="center")
            elif col_name == 'სტატუსი':
                cell.alignment = Alignment(horizontal="center", vertical="center")
                if 'გადაცილება' in str(val):
                    cell.fill = fill_red
                    cell.font = font_red
                else:
                    cell.fill = fill_green
                    cell.font = font_green
            else:
                cell.alignment = Alignment(horizontal="left", vertical="center")
                
        row_idx += 1

    ws.cell(row=row_idx, column=1, value="სულ ჯამი:").font = font_bold
    ws.cell(row=row_idx, column=7, value=summary_df['სულ ცალი'].sum()).font = font_bold
    ws.cell(row=row_idx, column=8, value=round(summary_df['სულ წონა (კგ)'].sum(), 1)).font = font_bold
    ws.cell(row=row_idx, column=9, value=summary_df['სულ პალეტი'].sum()).font = font_bold
    ws.cell(row=row_idx, column=10, value=summary_df['ტევადობა'].sum()).font = font_bold
    
    for c in range(1, len(cols) + 1):
        ws.cell(row=row_idx, column=c).border = Border(top=Side(style="thin", color="1F497D"), bottom=Side(style="double", color="1F497D"))
        if c in [7, 8, 9, 10]:
            ws.cell(row=row_idx, column=c).alignment = Alignment(horizontal="right", vertical="center")

    col_widths = {1: 26, 2: 20, 3: 38, 4: 22, 5: 25, 6: 25, 7: 15, 8: 16, 9: 14, 10: 14, 11: 26}
    for c, w in col_widths.items():
        ws.column_dimensions[get_column_letter(c)].width = w

    ws.freeze_panes = "B5"

    output = io.BytesIO()
    wb.save(output)
    output.seek(0)
    return output

